// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// ✦ Xiuu · Clawdy · Desktop band
// © 2026 Xiuu · Released under the MIT License, see LICENSE.
// ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
import type { Elements, RenderElement } from 'claude-code'

import type { Gauge, Snapshot } from '../types'
import { CARD_TITLES, COLORS, DESKTOP as D, GLYPHS, HEAT, WARN_AT } from './config'
import { effortGlyphs } from './effort'
import { formatModel, formatReset, formatTokens, scale, tone } from './format'
import { frameFor, pixelsOf } from './pet'

// The Desktop app draws a Box as a flex div and a Text as a span in a proportional font,
// and has no Raster. So the band is one SVG: drawn as an image, scaled to its slot, the
// same everywhere. Clawd keeps his pixels, from the very frames the terminal packs.

type Ui = Pick<Elements['desktop'], 'Svg'>

export type DeskInput = {
  snap: Snapshot
  columns: number
  now: number
  frame: number
  isMoving: boolean
  pet: ReturnType<typeof frameFor> | null
}

const clamp = (n: number) => Math.max(0, Math.min(100, Math.round(n)))
const L = D.card.lines
const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
const hex = (n: number) => '#' + (n & 0xffffff).toString(16).padStart(6, '0')

/** Cuts a string to what fits in `px`, at the font's average width. */
function fit(s: string, px: number): string {
  const max = Math.max(1, Math.floor(px / (D.fontSize * 0.56)))
  return s.length > max ? s.slice(0, Math.max(1, max - 1)) + '…' : s
}

function folderName(cwd: string): string {
  const parts = cwd.replace(/\\/g, '/').split('/').filter(Boolean)
  return parts[parts.length - 1] ?? cwd
}

// ============ PIECES ============

type Anchor = 'start' | 'end'

function text(x: number, y: number, body: string, cls: string, opts: { anchor?: Anchor; bold?: boolean } = {}): string {
  const anchor = opts.anchor === 'end' ? ' text-anchor="end"' : ''
  const weight = opts.bold ? ' font-weight="600"' : ''
  return `<text x="${x}" y="${y}" class="${cls}"${anchor}${weight}>${body}</text>`
}

/** A bar of pixel blocks, filled left to right through the heat scale, green to red. */
function bar(x: number, y: number, width: number, percent: number): string {
  const step = D.bar.block + D.bar.gap
  const n = Math.max(4, Math.floor((width + D.bar.gap) / step))
  const filled = Math.round((clamp(percent) * n) / 100)
  let out = ''
  for (let i = 0; i < n; i++) {
    const at = `x="${x + i * step}" y="${y}" width="${D.bar.block}" height="${D.bar.height}"`
    out += i < filled ? `<rect ${at} fill="${scale(HEAT, n > 1 ? i / (n - 1) : 0)}"/>` : `<rect ${at} class="track"/>`
  }
  return out
}

function percent(x: number, y: number, value: number | undefined): string {
  if (value === undefined) return text(x, y, '-', 'f', { anchor: 'end' })
  const p = clamp(value)
  return `<text x="${x}" y="${y}" text-anchor="end" font-weight="700" fill="${scale(HEAT, p / 100)}">${p}%</text>`
}

function title(x: number, y: number, which: keyof typeof CARD_TITLES): string {
  const t = CARD_TITLES[which]
  return text(x, y, esc(`${t.icon} ${t.title}`), 't', { bold: true })
}

function frameRect(x: number, y: number, w: number, h: number, accent?: string): string {
  const stroke = accent ? ` style="stroke:${accent}"` : ''
  // the band renders crisp for Clawd's pixels; a card's rounded corners stay smooth
  return `<rect x="${x + 0.5}" y="${y + 0.5}" width="${w - 1}" height="${h - 1}" rx="${D.card.radius}" class="card" shape-rendering="geometricPrecision"${stroke}/>`
}

/** Clawd: one rect per run of same-colored pixels, his glyphs in a monospace face. */
function clawd(ox: number, oy: number, frame: ReturnType<typeof frameFor>): string {
  const { width, height, colors, glyphs, empty } = pixelsOf(frame)
  const { w, h } = D.pixel
  let out = ''
  for (let y = 0; y < height; y++) {
    let x = 0
    while (x < width) {
      const c = colors[y * width + x] ?? empty
      let run = 1
      while (x + run < width && colors[y * width + x + run] === c) run++
      if (c !== empty) out += `<rect x="${ox + x * w}" y="${oy + y * h}" width="${run * w}" height="${h}" fill="${hex(c)}"/>`
      x += run
    }
  }
  for (const g of glyphs) {
    const gx = ox + g.cx * 2 * w + w
    const gy = oy + g.cy * 2 * h + h * 1.6
    out += `<text x="${gx}" y="${gy}" text-anchor="middle" font-family="Consolas, monospace" font-weight="700" fill="${hex(g.color)}">${esc(g.char)}</text>`
  }
  return out
}

// ============ CARDS ============

type Box = { x: number; y: number; w: number; h: number }

function modelCard(b: Box, { snap, frame, isMoving }: DeskInput): string {
  const i = D.card.inset
  const effort = snap.effort
    ? effortGlyphs(snap.effort, frame, isMoving).map(g => `<tspan fill="${g.color}">${esc(g.char)}</tspan>`).join('')
    : ''
  return [
    frameRect(b.x, b.y, b.w, b.h),
    title(b.x + i, b.y + L.title, 'model'),
    text(b.x + i, b.y + L.mid, esc(fit(formatModel(snap.model), b.w - 2 * i)), 't'),
    effort ? `<text x="${b.x + i}" y="${b.y + L.low}" font-weight="600">${effort}</text>` : '',
  ].join('')
}

function contextCard(b: Box, { snap }: DeskInput): string {
  const i = D.card.inset
  const ctx = snap.context
  const p = ctx.percent ?? 0
  return [
    frameRect(b.x, b.y, b.w, b.h, p >= WARN_AT ? tone(p) : undefined),
    title(b.x + i, b.y + L.title, 'context'),
    percent(b.x + b.w - i, b.y + L.title, p),
    bar(b.x + i, b.y + L.mid - D.bar.lift, b.w - 2 * i, p),
    text(b.x + i, b.y + L.low, esc(`${formatTokens(ctx.tokens ?? 0)} / ${formatTokens(ctx.window)}`), 'm'),
  ].join('')
}

function usageCard(b: Box, { snap, now }: DeskInput): string {
  const i = D.card.inset
  const right = b.x + b.w - i
  const resetW = 64
  const pctW = 40
  const barX = b.x + i + 24
  const barW = Math.max(24, right - resetW - pctW - 8 - barX)
  const line = (y: number, name: string, gauge: Gauge | undefined) => {
    const reset = formatReset(gauge?.resetsAt, now)
    return [
      text(b.x + i, y, name, 'm'),
      bar(barX, y - D.bar.lift, barW, gauge?.percent ?? 0),
      percent(right - resetW - 4, y, gauge?.percent),
      reset ? text(right, y, esc(`${GLYPHS.reset} ${reset}`), 'm', { anchor: 'end' }) : '',
    ].join('')
  }
  const worst = Math.max(snap.session?.percent ?? 0, snap.week?.percent ?? 0)
  return [
    frameRect(b.x, b.y, b.w, b.h, worst >= WARN_AT ? tone(worst) : undefined),
    title(b.x + i, b.y + L.title, 'usage'),
    line(b.y + L.mid, '5h', snap.session),
    line(b.y + L.low, '7d', snap.week),
  ].join('')
}

function projectCard(b: Box, { snap }: DeskInput): string {
  const i = D.card.inset
  const g = snap.git
  const sync = g ? [g.ahead ? `${GLYPHS.ahead}${g.ahead}` : '', g.behind ? `${GLYPHS.behind}${g.behind}` : ''].filter(Boolean).join(' ') : ''
  const isClean = g !== null && !g.added && !g.deleted && !g.changed
  const gitLine = g
    ? `<text x="${b.x + i}" y="${b.y + L.low}"><tspan class="m">${esc(fit(`${GLYPHS.branch} ${g.branch}`, b.w / 2))}</tspan>` +
      (isClean ? `<tspan fill="${COLORS.add}">   ${GLYPHS.clean} clean</tspan>` : '') +
      (g.added ? `<tspan fill="${COLORS.add}">   +${g.added}</tspan>` : '') +
      (g.deleted ? `<tspan fill="${COLORS.remove}">  -${g.deleted}</tspan>` : '') +
      `</text>`
    : text(b.x + i, b.y + L.low, 'no git', 'f')
  return [
    frameRect(b.x, b.y, b.w, b.h),
    title(b.x + i, b.y + L.title, 'project'),
    sync ? text(b.x + b.w - i, b.y + L.title, esc(sync), 'm', { anchor: 'end' }) : '',
    text(b.x + i, b.y + L.mid, esc(fit(folderName(snap.cwd), b.w - 2 * i)), 't'),
    gitLine,
  ].join('')
}

// ============ BAND ============

function style(): string {
  const rules = (t: typeof D.dark | typeof D.light) =>
    `.t{fill:${t.text}}.m{fill:${t.muted}}.f{fill:${t.faint}}.card{fill:${t.fill};stroke:${t.stroke}}.track{fill:${t.track}}`
  return `<style>text{font-family:${D.font};font-size:${D.fontSize}px}${rules(D.dark)}@media (prefers-color-scheme: light){${rules(D.light)}}</style>`
}

function alt({ snap }: DeskInput): string {
  const parts = [
    `${formatModel(snap.model)}${snap.effort ? ` ${snap.effort}` : ''}`,
    `context ${clamp(snap.context.percent ?? 0)}%`,
    snap.session ? `5h ${clamp(snap.session.percent)}%` : '',
    snap.week ? `7d ${clamp(snap.week.percent)}%` : '',
    `project ${folderName(snap.cwd)}`,
  ]
  return `Clawd beside the cards: ${parts.filter(Boolean).join(', ')}`
}

export function drawDesktop({ Svg }: Ui, input: DeskInput): RenderElement {
  const W = Math.max(480, Math.round(input.columns * D.pxPerColumn))
  const petW = input.pet ? (pixelsOf(input.pet).width * D.pixel.w) : 0
  const petH = input.pet ? (pixelsOf(input.pet).height * D.pixel.h) : 0
  const cardsX = D.pad + (petW ? petW + D.gap + 4 : 0)
  const cardsW = W - cardsX - D.pad
  const perRow = (cardsW - 3 * D.gap) / 4 >= D.card.rowFrom ? 4 : 2
  const cardW = Math.floor((cardsW - (perRow - 1) * D.gap) / perRow)
  const rows = 4 / perRow
  const H = 2 * D.pad + rows * D.card.height + (rows - 1) * D.gap

  const cards = [modelCard, contextCard, usageCard, projectCard].map((draw, k) => {
    const box = {
      x: cardsX + (k % perRow) * (cardW + D.gap),
      y: D.pad + Math.floor(k / perRow) * (D.card.height + D.gap),
      w: cardW,
      h: D.card.height,
    }
    return draw(box, input)
  })

  const pet = input.pet ? clawd(D.pad, Math.round((H - petH) / 2), input.pet) : ''
  const source =
    `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" shape-rendering="crispEdges">` +
    style() +
    pet +
    cards.join('') +
    `</svg>`
  return <Svg source={source} alt={alt(input)} />
}

