  branch: string
  added: number
  deleted: number
  changed: number
  ahead: number
  behind: number
}

export type Snapshot = {
  model: string
  effort?: string
  cwd: string
  costUsd?: number
  home?: string
  context: { tokens?: number; window: number; percent?: number }
  session?: Gauge
  week?: Gauge
